#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n;
    cin >> n;

    vector<int> digits;
    while (n > 0) {
        digits.push_back(n % 3);
        n /= 3;
    }

    ll ans = 0;
    int first = -1;

    for (int i = 0; i < static_cast<int>(digits.size()); ++i) {
        if (digits[i] == 0) continue;

        if (first == -1) {
            first = i;
            ans = 1;
        } else {
            ll value = 1;
            for (int j = 0; j < i - first - 1; ++j)
                value *= 3;
            ans += value * digits[i];
        }
    }

    cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;

    if (n == 0) {
        cout << 0 << '\n';
        return 0;
    }

    vector<int> digits;
    while (n > 0) {
        digits.push_back(n % 3);
        n /= 3;
    }

    size_t first = 0;
    while (first < digits.size() && digits[first] == 0) {
        ++first;
    }

    long long ans = 1;
    long long weight = 1;

    for (size_t i = first + 1; i < digits.size(); ++i) {
        ans += digits[i] * weight;
        if (i + 1 < digits.size()) {
            weight *= 3;
        }
    }

    cout << ans << '\n';
    return 0;
}

